import { createHash } from "node:crypto"

import { createR2Store, imagePublicUrl, r2Config, type ObjectStore, verifyPublicImage } from "@/lib/r2"

export type ImageBlock = {
  id?: string
  type: string
  image?: {
    type?: string
    external?: { url?: string }
    file?: { url?: string }
    caption?: unknown[]
  }
  children?: ImageBlock[]
  [key: string]: unknown
}

type DownloadedImage = { body: Uint8Array; contentType: string }
type ImageDownloader = (url: string, maxBytes: number) => Promise<DownloadedImage | undefined>

const defaultMaxBytes = 10 * 1024 * 1024
const imageTypes = new Set(["image/jpeg", "image/png", "image/gif", "image/webp", "image/avif"])

function maxImageBytes(): number {
  const value = Number(process.env.R2_MAX_IMAGE_BYTES)
  return Number.isSafeInteger(value) && value > 0 ? value : defaultMaxBytes
}

function allowedHosts(): Set<string> {
  return new Set((process.env.NOTION_FILE_HOSTS ?? "").split(",").map((host) => host.trim().toLowerCase()).filter(Boolean))
}

function sourceUrl(value: string | undefined): URL | undefined {
  if (!value) return undefined
  try {
    const url = new URL(value)
    if (url.protocol !== "https:" || !allowedHosts().has(url.hostname.toLowerCase())) return undefined
    return url
  } catch {
    return undefined
  }
}

function stableSource(url: URL): string {
  const path = url.pathname.replace(/\\+/g, "/")
  const match = path.match(/(?:^|\/)([0-9a-f]{32})(?:\/|$)/i)
  return `${url.hostname.toLowerCase()}/${match?.[1] ?? path}`
}

export function imageStorageKey(url: string): string | undefined {
  const source = sourceUrl(url)
  if (!source) return undefined
  const digest = createHash("sha256").update(stableSource(source)).digest("hex")
  const extension = source.pathname.match(/\.([a-z0-9]{2,5})$/i)?.[1]?.toLowerCase() ?? "bin"
  return `notion/${digest}.${extension}`
}

async function defaultDownload(url: string, limit: number): Promise<DownloadedImage | undefined> {
  const source = sourceUrl(url)
  if (!source) return undefined
  try {
    const response = await fetch(source, { redirect: "error", signal: AbortSignal.timeout(10_000) })
    if (!response.ok) return undefined
    const contentType = response.headers.get("content-type")?.split(";", 1)[0].toLowerCase() ?? ""
    if (!imageTypes.has(contentType)) return undefined
    const contentLength = Number(response.headers.get("content-length"))
    if (Number.isFinite(contentLength) && contentLength > limit) return undefined
    if (!response.body) return undefined
    const reader = response.body.getReader()
    const chunks: Uint8Array[] = []
    let total = 0
    try {
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        total += value.byteLength
        if (total > limit) return undefined
        chunks.push(value)
      }
    } finally {
      reader.releaseLock()
    }
    const body = new Uint8Array(total)
    let offset = 0
    for (const chunk of chunks) {
      body.set(chunk, offset)
      offset += chunk.byteLength
    }
    return { body, contentType }
  } catch {
    return undefined
  }
}

function cloneWithUrl(block: ImageBlock, url: string): ImageBlock {
  return { ...block, image: { ...block.image, file: { ...block.image?.file, url } } }
}

export type ImageSyncDependencies = {
  store: ObjectStore
  download?: ImageDownloader
  verify?: (url: string, contentType: string) => Promise<boolean>
  publicBaseUrl: string
  maxBytes?: number
}

export function createImageSyncDependencies(): ImageSyncDependencies | undefined {
  const config = r2Config()
  const store = config ? createR2Store(config) : undefined
  if (!config || !store) return undefined
  return { store, publicBaseUrl: config.publicBaseUrl }
}

function logFailure(url: string, reason: string): void {
  const source = sourceUrl(url)
  console.error("Notion image persistence failed", {
    host: source?.hostname,
    path: source?.pathname,
    reason,
  })
}

export async function persistNotionImages(
  blocks: ImageBlock[],
  dependencies = createImageSyncDependencies(),
): Promise<ImageBlock[]> {
  if (!dependencies) return blocks
  const deps = dependencies
  const downloader = deps.download ?? defaultDownload
  const verify = deps.verify ?? ((url, type) => verifyPublicImage(url, type))
  const maxBytes = deps.maxBytes ?? maxImageBytes()
  const cache = new Map<string, Promise<string | undefined>>()

  async function persist(url: string, key: string): Promise<string | undefined> {
    const existing = await deps.store.head(key)
    const existingType = existing?.contentType?.split(";", 1)[0].toLowerCase()
    const candidate = imagePublicUrl(deps.publicBaseUrl, key)
    if (existing && existingType && imageTypes.has(existingType) && await verify(candidate, existingType)) return candidate

    const downloaded = await downloader(url, maxBytes)
    if (!downloaded) {
      logFailure(url, "download rejected or failed")
      return undefined
    }
    await deps.store.put(key, downloaded.body, downloaded.contentType)
    if (!await verify(candidate, downloaded.contentType)) {
      logFailure(url, "public URL verification failed")
      return undefined
    }
    return candidate
  }

  async function visit(block: ImageBlock): Promise<ImageBlock> {
    let result = block
    if (block.type === "image" && block.image?.type === "file") {
      const original = block.image.file?.url
      const key = imageStorageKey(original ?? "")
      if (original && key) {
        let pending = cache.get(key)
        if (!pending) {
          pending = persist(original, key).catch((error: unknown) => {
            logFailure(original, error instanceof Error ? error.message : "storage operation failed")
            return undefined
          })
          cache.set(key, pending)
        }
        const url = await pending
        if (url) result = cloneWithUrl(block, url)
      }
    }
    if (block.children?.length) result = { ...result, children: await Promise.all(block.children.map(visit)) }
    return result
  }

  return Promise.all(blocks.map(visit))
}
