import { HeadObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3"

export type ObjectStore = {
  head(key: string): Promise<{ contentType?: string } | undefined>
  put(key: string, body: Uint8Array, contentType: string): Promise<void>
}

function required(name: string): string | undefined {
  const value = process.env[name]?.trim()
  return value || undefined
}

export function r2Config() {
  const accountId = required("R2_ACCOUNT_ID")
  const accessKeyId = required("R2_ACCESS_KEY_ID")
  const secretAccessKey = required("R2_SECRET_ACCESS_KEY")
  const bucket = required("R2_BUCKET_NAME")
  const publicBaseUrl = required("R2_PUBLIC_BASE_URL")?.replace(/\/$/, "")
  if (!accountId || !accessKeyId || !secretAccessKey || !bucket || !publicBaseUrl) return undefined
  return { accountId, accessKeyId, secretAccessKey, bucket, publicBaseUrl }
}

export function imagePublicUrl(baseUrl: string, key: string): string {
  return `${baseUrl.replace(/\/$/, "")}/${key.split("/").map(encodeURIComponent).join("/")}`
}

export function createR2Store(config = r2Config()): ObjectStore | undefined {
  if (!config) return undefined
  const client = new S3Client({
    region: "auto",
    endpoint: `https://${config.accountId}.r2.cloudflarestorage.com`,
    credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey },
  })
  return {
    async head(key) {
      try {
        const result = await client.send(new HeadObjectCommand({ Bucket: config.bucket, Key: key }))
        return { contentType: result.ContentType }
      } catch (error) {
        const status = error && typeof error === "object" && "$metadata" in error
          ? (error as { $metadata?: { httpStatusCode?: number } }).$metadata?.httpStatusCode
          : undefined
        if (status === 404 || (error instanceof Error && error.name === "NotFound")) return undefined
        throw error
      }
    },
    async put(key, body, contentType) {
      await client.send(new PutObjectCommand({ Bucket: config.bucket, Key: key, Body: body, ContentType: contentType }))
    },
  }
}

export async function verifyPublicImage(url: string, contentType: string, fetcher = fetch): Promise<boolean> {
  try {
    const response = await fetcher(url, { method: "HEAD", redirect: "error", signal: AbortSignal.timeout(10_000) })
    if (!response.ok) return false
    const actual = response.headers.get("content-type")?.split(";", 1)[0].toLowerCase()
    return actual === contentType
  } catch {
    return false
  }
}

export function storedImage(config: NonNullable<ReturnType<typeof r2Config>>, key: string, contentType: string): StoredImage {
  return { key, contentType, url: imagePublicUrl(config.publicBaseUrl, key) }
}
